_:nace15f8fb2104fc6bb46f775f36e695bb1 sh:message "Referenced features must be present within current graph closure for  topological feature." ;
    sh:select """
        prefix rdf:     <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
        PREFIX rdfs:    <http://www.w3.org/2000/01/rdf-schema#>
        prefix geojson: <https://purl.org/geojson/vocab#>
        prefix topo: <https://purl.org/geojson/topo#>
        SELECT $this (topo:relatedFeatures as ?path) (?ref as ?value)
        WHERE {
         $this topo:relatedFeatures/rdf:rest*/rdf:first ?ref .
         $this a ?geomtype .
         FILTER ( ?geomtype != geojson:Polygon)
         FILTER NOT EXISTS { ?ref ?p ?o }
        }
""" .

_:nace15f8fb2104fc6bb46f775f36e695bb3 sh:message "Lines topologies must reference points within current graph closure." ;
    sh:select """
        prefix rdf:     <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
        PREFIX rdfs:    <http://www.w3.org/2000/01/rdf-schema#>
        prefix geojson: <https://purl.org/geojson/vocab#>
        prefix dct:     <http://purl.org/dc/terms/>
        PREFIX geosparql: <http://www.opengis.net/ont/geosparql#>
        prefix topo: <https://purl.org/geojson/topo#>
        SELECT $this (geojson:topology as ?path) (?ref as ?value)
        WHERE {
         $this topo:relatedFeatures/rdf:rest*/rdf:first ?ref .
         FILTER NOT EXISTS {
             ?ref (geojson:geometry|geosparql:hasGeometry|dct:spatial)/rdf:type geojson:Point }
        }
""" .

